I tested quickly assigning from code with non typed array and non typed variable, duplication seems to work correctly:

![image](https://github.com/godotengine/godot/assets/33091666/1c1bd6cf-4d53-4325-8495-943486ab7b17)


```
extends Node3D

@export var health: float = 100
@export var cube: Node3D = null
@export var cubes: Array[Node3D] = []
var non_typed_array: Array = []
var non_typed_node = null

# Called when the node enters the scene tree for the first time.
func _ready() -> void:
	health = PlayerStats.player_health
	non_typed_node = get_node("MeshInstance3D")
	non_typed_array.push_back(get_node("MeshInstance3D"))
	if name == "Cube":
		var dup_node: Node3D = duplicate()
		get_tree().get_current_scene().add_child.call_deferred(dup_node)
		dup_node.global_position.x += 3
	print(non_typed_array[0])

# Called every frame. 'delta' is the elapsed time since the previous frame.
func _physics_process(delta: float) -> void:
	if Input.is_action_just_pressed("hurt_self"):
		health -= 10
		PlayerStats.player_health = health
		print(health)
	if Input.is_action_just_pressed('switch_level'):
		get_tree().change_scene_to_file("res://scene_2.tscn")
	if non_typed_array.size() > 0:
		non_typed_array[0].rotation.y += 90 * delta
```
